[dependencies]
# Find and replace over the buffer. The bar model is kate_search::FindBar.
kate-search = { workspace = true }

/// The items below are pub(crate).
/// The find bar and its open flags.
#[derive(Clone, Debug, Default)]
struct FindState {
    pub bar: kate_search::FindBar,
    pub open: bool,
    pub with_replace: bool,
}

/// The items below are pub(crate).
/// MoveTo the next hit from `from`, or None when there is no hit or the pattern is bad.
fn find_command(state: &FindState, buf: &kate_text::TextBuffer, from: kate_text::Offset) -> Option<kate_core::Command>
/// ReplaceRanges for one hit.
fn replace_one_command(state: &FindState, buf: &kate_text::TextBuffer, hit: &kate_search::Match) -> Option<kate_core::Command>
/// ReplaceRanges for every hit.
fn replace_all_command(state: &FindState, buf: &kate_text::TextBuffer) -> Option<kate_core::Command>
/// (range, text) pairs from the edits of a transaction.
fn pairs_from(tx: &kate_text::Transaction) -> Vec<(kate_text::CharRange, String)>
